    "content": "德国《经济周刊》获得的一份147页大众汽车内部文件显示，大众汽车管理董事会已一致通过方案，计划陆续关停4座德国境内的汽车工厂。据德国《图片报》2日报道，大众汽车计划将位于埃姆登和茨维考的两座工厂于2031年停产，位于汉诺威的大众商用车工厂将在2032年停产，而位于内卡苏尔姆的奥迪工厂则将在2034年停产。相关文件显示，受当前市场趋势影响，仅大众汽车集团在欧洲的产能就出现了“超过50万辆的过剩”。大众汽车目前已无法确保4家工厂在未来能获得具有竞争力的车型生产配额。（环球网）"
