    "content": "2026年09月03日 站在25周年的新起点上，中方将同各方一道，继续高举“上海精神”旗帜，落实上海合作组织未来10年发展战略，努力实现更高质量发展，为推动构建人类命运共同体作出更大上合贡献 9月1日，习近平主席在比什凯克出席上海合作组织成员国元首理事会第二十六次会议、“上海合作组织+”会议，并发表重要讲话，为推动上海合作组织实现更高质量发展，共同倡导平等有序的世界多极化，实现更加公正合理的全球治理指明前进方向。 25年前，面对冷战的深刻教训、“三股势力”的现实威胁和各国人民对和平与发展的热切期盼，上海合作组织应运…"
