    "description": "2026年09月03日 “习近平主席时隔10年再次访问埃及，是埃中关系发展的一件大事。”埃及中国问题专家萨维在开罗接受本报记者采访时说，“此次访问既是对过去10年埃中合作成果的回望，也为两国关系未来发展注入新的动力。” 在萨维看来，“10年”是理解此次访问的一个重要时间坐标。2014年，两国元首共同决定将中埃关系提升为全面战略伙伴关系。2016年1月，习近平主席对埃及进行国事访问，双方发表关于加强全面战略伙伴关系的五年实施纲要。10年来…",
