    "content": "2026年09月03日 本报福州9月2日电&nbsp;&nbsp;（记者付文）记者从福州边检站获悉：今年7月1日至8月30日，福马“小三通”客运航线累计出入境旅客2.3万余人次，比去年暑假期间增长约26%，创下2023年复航以来暑期客流新高。 目前，福州至马祖之间有连江黄岐至马祖、马尾至马祖两条“小三通”客运航线，每日共8趟航班来往两岸。进入暑期后，“两马”（马尾、马祖）体育交流、文化交流等活动相继开展，推动福马“小三通”客运航线迎来客流高峰。据福州边检站介绍，往来旅客中亲子游占据主流，参加研学交流、商务访问的旅客…"
