    "content": "2026年09月03日 拥有119家国家级制造业单项冠军企业，数量连续8年居全国城市首位；1万余家高新技术企业、511家专精特新“小巨人”深耕细分领域……浙江宁波因制造而立、因港口而兴，始终坚持脚踏实地做强实体经济，向技术挖掘增长潜力，凭开放拓展发展空间。 习近平总书记指出：“不论经济发展到什么时候，实体经济都是我国经济发展、我们在国际经济竞争中赢得主动的根基。我国经济是靠实体经济起家的，也要靠实体经济走向未来。” 牢记总书记嘱托，宁波始终坚持把发展经济的着力点放在实体经济上，推动科技创新和产业创新深度融合，构建优…"
