    "description": "2026年09月03日 贵州贵阳，甲秀楼人声鼎沸。不远处的几家茶饮门店里，同样客流不断。广东游客王秀艳在茶饮店“去茶山”点了一杯“贵阳冰茶”，轻抿一口，刺梨的山野风味在舌尖绽开：“酸涩之后有回甘，味道很好。就像贵州的山水，越品越有味！” “贵阳新茶饮，在网上可火了。”王秀艳边品茶边惬意地欣赏着窗外风景，说起自己的行程：“这次来贵阳，除了品美食看风景，我还专门留了一天时间在城里慢慢逛、慢慢喝，细细感受贵阳味道。” 如今，到贵阳喝一杯特色饮…",
    "content": "2026年09月03日 贵州贵阳，甲秀楼人声鼎沸。不远处的几家茶饮门店里，同样客流不断。广东游客王秀艳在茶饮店“去茶山”点了一杯“贵阳冰茶”，轻抿一口，刺梨的山野风味在舌尖绽开：“酸涩之后有回甘，味道很好。就像贵州的山水，越品越有味！” “贵阳新茶饮，在网上可火了。”王秀艳边品茶边惬意地欣赏着窗外风景，说起自己的行程：“这次来贵阳，除了品美食看风景，我还专门留了一天时间在城里慢慢逛、慢慢喝，细细感受贵阳味道。” 如今，到贵阳喝一杯特色饮品，正成为年轻游客打卡这座城市的必选项。“很多游客起初只是买杯奶茶解渴，后来追着…"
