    "author": "",
    "description": "2026年09月03日 本报北京9月2日电 （记者李晓晴）记者从自然资源部获悉：我国新一轮找矿突破战略行动再获标志性成果，安徽宣城市茶亭地区铜金矿勘查取得重大突破，有望在华东地区形成新的大型铜金资源基地，对于提升我国铜、金资源安全保障能力具有重大战略意义。 茶亭铜金矿床坐落于长江中下游成矿带南陵—宣城铜金矿集区，地处长三角腹地，是近年来我国在火山岩覆盖区新发现的具有超大型规模潜力的隐伏斑岩型铜金矿床。矿区主矿体长约1.2千米，宽约1.1…",
    "content": "2026年09月03日 本报北京9月2日电&nbsp;&nbsp;（记者李晓晴）记者从自然资源部获悉：我国新一轮找矿突破战略行动再获标志性成果，安徽宣城市茶亭地区铜金矿勘查取得重大突破，有望在华东地区形成新的大型铜金资源基地，对于提升我国铜、金资源安全保障能力具有重大战略意义。 茶亭铜金矿床坐落于长江中下游成矿带南陵—宣城铜金矿集区，地处长三角腹地，是近年来我国在火山岩覆盖区新发现的具有超大型规模潜力的隐伏斑岩型铜金矿床。矿区主矿体长约1.2千米，宽约1.1千米，单孔矿体最大视厚度达1371米。初步估算，铜潜在资源…"
