    "author": "",
    "description": "2026年09月03日 9月1日，辽宁多个沿海城市迎来“开海”，一艘艘钢制渔船从大连的渔港驶出，开展捕捞作业（无人机照片）。 近年来，辽宁通过整合政策、优化服务，大力推进海洋捕捞渔船“木改钢”，并以此为切入口破解渔船合规、出海安全、捕捞秩序等方面的难题。截至今年7月，辽宁已启动更新改造渔船超1700艘，有效提升了渔船作业安全。 吕文正摄（新华社发） 2026-09-03 00:00:00:0 30178859 10http://pape…",
