    "content": "2026年09月03日 本报北京9月2日电&nbsp;&nbsp;（记者吴储岐）记者从民政部获悉：民政部、中央社会工作部、财政部、全国老龄办、中国老龄协会等五部门日前联合印发通知，将组织开展第六次中国城乡老年人生活状况抽样调查，为深入实施积极应对人口老龄化国家战略，完善相关法律、法规和政策，提供基础数据保障。 本次调查对象分为老年人、老年人所在社区（村）两种类型。其中，老年人为居住在中华人民共和国境内（不包括台湾省、香港特别行政区和澳门特别行政区）、截至2026年9月1日零时年满60周岁及以上的中国公民。调查范围为…"
