    "content": "2026年09月03日 发展新质生产力的基本路径是科技创新和产业创新，知识产权保护在这一过程中发挥重要作用。习近平总书记指出：“要完善知识产权保护制度，打破高校、科研院所、企业之间创新要素的流动壁垒。”“十五五”规划纲要提出“完善新兴领域知识产权保护制度，健全知识产权公共服务体系和技术交易服务平台网络”。前不久国务院印发的《知识产权保护和运用“十五五”规划》提出“加大促进新质生产力发展的知识产权供给”并作出具体部署。抓住关键环节完善知识产权保护制度，对于激发创新创造活力、加快科技成果转化具有重要意义。 知识产权是国…"
