    "description": "2026年09月03日 清晨6点，重庆万州区长滩镇龙泉社区一家生态养殖场，薄雾贴着水面慢慢散开。 56岁的养殖户傅永祥蹲在塘埂上，手里的半把鱼食轻轻一撒，水面上泛起圈圈涟漪，几十条四鼻鲤鱼摆着尾巴蹿上来抢食，“你看这鱼，精神得很。” 5年前，傅永祥怎么也想不到——山东微山湖的鱼苗，能游在他家的池塘里，还能把他的日子“烤”得红红火火。 而这一切，都要从一场跨越山海的协作说起。 2021年，时任山东济宁市农业农村局副局长的魏昌彦挂职重庆万州…",
    "content": "2026年09月03日 清晨6点，重庆万州区长滩镇龙泉社区一家生态养殖场，薄雾贴着水面慢慢散开。 56岁的养殖户傅永祥蹲在塘埂上，手里的半把鱼食轻轻一撒，水面上泛起圈圈涟漪，几十条四鼻鲤鱼摆着尾巴蹿上来抢食，“你看这鱼，精神得很。” 5年前，傅永祥怎么也想不到——山东微山湖的鱼苗，能游在他家的池塘里，还能把他的日子“烤”得红红火火。 而这一切，都要从一场跨越山海的协作说起。 2021年，时任山东济宁市农业农村局副局长的魏昌彦挂职重庆万州区农业农村委员会副主任，初到万州的他发现，这里虽有世代相传的烤鱼技艺，却面临禁渔…"
