    "author": "",
    "description": "2026年09月03日 城市商圈最金贵的外墙广告位，最近悄悄换了主角。在山东菏泽、内蒙古呼伦贝尔、安徽合肥等地，多家商场换上钱学森、邓稼先等科学家的公益海报。市民随手拍下，收获网友众多点赞。 当下，敬重科研、崇尚科学的风气越来越浓厚。黄旭华、南仁东等科学家的奋斗故事在社交平台广泛传播，王虹、邓煜斩获菲尔兹奖的喜讯也受到持续关注。这样的传播形式，消解了科研领域的距离感，让年轻人读懂了榜样力量。商场外墙的公益广告更让这份氛围，融入市民日常。…",
    "content": "2026年09月03日 城市商圈最金贵的外墙广告位，最近悄悄换了主角。在山东菏泽、内蒙古呼伦贝尔、安徽合肥等地，多家商场换上钱学森、邓稼先等科学家的公益海报。市民随手拍下，收获网友众多点赞。 当下，敬重科研、崇尚科学的风气越来越浓厚。黄旭华、南仁东等科学家的奋斗故事在社交平台广泛传播，王虹、邓煜斩获菲尔兹奖的喜讯也受到持续关注。这样的传播形式，消解了科研领域的距离感，让年轻人读懂了榜样力量。商场外墙的公益广告更让这份氛围，融入市民日常。 长久以来，有些人习惯将商业经营与社会责任割裂开来。可商业空间同样属于城市公共场…"
