    "description": "2026年09月03日 四川凉山彝族自治州是得天独厚的天然温室，年产会理石榴100万吨、盐源苹果60万吨、各类葡萄80万吨，堪称“天然果篮”。然而过去很长一段时间，鲜果出山主要靠公路运输，时间长、损耗高，销售半径受限。 8月28日上午，首趟搭载了14个40英尺“背包式”冷藏集装箱的“甬凉号”乡村振兴班列从凉山州西昌市出发，满载300吨新鲜葡萄和桑葚一路向东，3天后抵达浙江杭州。 在西昌一处葡萄园，农场负责人颜辉正在采摘葡萄。“要赶在太阳…",
    "content": "2026年09月03日 四川凉山彝族自治州是得天独厚的天然温室，年产会理石榴100万吨、盐源苹果60万吨、各类葡萄80万吨，堪称“天然果篮”。然而过去很长一段时间，鲜果出山主要靠公路运输，时间长、损耗高，销售半径受限。 8月28日上午，首趟搭载了14个40英尺“背包式”冷藏集装箱的“甬凉号”乡村振兴班列从凉山州西昌市出发，满载300吨新鲜葡萄和桑葚一路向东，3天后抵达浙江杭州。 在西昌一处葡萄园，农场负责人颜辉正在采摘葡萄。“要赶在太阳上来前摘完。”他说，冷链车很快到，摘下的果子得抓紧送冻库预冷，时间越短、损耗越小…"
