    "description": "2026年09月03日 8月30日清晨，家住云南曲靖宣威市普立乡尼珠河村的学生雷鑫背起书包，与同村的小伙伴一起，去隔壁镇的一所中学报到。 与多数同龄人不同，他们上学要乘坐被称为“空中校车”的悬崖电梯与高空索道缆车。 雷鑫的家在尼珠河大峡谷谷底。今年6月，雷鑫刚从山顶的官寨完小毕业。曾经，尼珠河村的学生外出求学，必须先到达山顶。而河谷崖壁的路沟壑纵横、陡峭湿滑，孩子们从村子到学校，手脚并用得花将近半天时间，一路很是艰难。 2022年，尼珠…",
    "content": "2026年09月03日 8月30日拍摄的官寨完小。 \"> 雷鑫（左一）和同村几名学生准备乘坐高空索道缆车。 \"> 8月30日清晨，家住云南曲靖宣威市普立乡尼珠河村的学生雷鑫背起书包，与同村的小伙伴一起，去隔壁镇的一所中学报到。 与多数同龄人不同，他们上学要乘坐被称为“空中校车”的悬崖电梯与高空索道缆车。 雷鑫的家在尼珠河大峡谷谷底。今年6月，雷鑫刚从山顶的官寨完小毕业。曾经，尼珠河村的学生外出求学，必须先到达山顶。而河谷崖壁的路沟壑纵横、陡峭湿滑，孩子们从村子到学校，手脚并用得花将近半天时间，一路很是艰难。 202…"
