    "description": "2026年09月03日 广东全民经典阅读大赛奖项公布 南方日报广州9月2日电 （记者戴雪晴）2026广东全民经典阅读大赛颁奖典礼暨舞台展演日前举行。大赛设置青少年、成人、家庭/团队三大赛道，共收到超1.6万份海选投稿，覆盖广东21个地市，最终决出各赛道一、二、三等奖。 2026版江苏省标准地图发布 新华日报南京9月2日电 （记者颜颖）日前，江苏省自然资源厅联合江苏省数据局发布2026版江苏省标准地图。 2026版江苏省标准地图总数增至7…",
