    "author": "",
    "description": "2026年09月03日 暑气渐渐消散，秋意浸染山野。 在生态农业种植基地，了解现代农业种植情况；在左右山谷景区，赏青山层峦环抱，看连片花田铺展眼前……近日，来自全国多地的20余名知名作家与文学创作者相聚河北秦皇岛市，开展“全国知名作家秦皇岛行”主题文学活动，一起深入田间、走进自然、分享交流，品味当地的人文底蕴与时代风貌。 燕山脚下的卢龙县是千年古县，这里浸润着独有的乡土气息。老马识途、李广射虎、金石为开……诸多耳熟能详的传说与成语典故发…",
    "content": "2026年09月03日 暑气渐渐消散，秋意浸染山野。 在生态农业种植基地，了解现代农业种植情况；在左右山谷景区，赏青山层峦环抱，看连片花田铺展眼前……近日，来自全国多地的20余名知名作家与文学创作者相聚河北秦皇岛市，开展“全国知名作家秦皇岛行”主题文学活动，一起深入田间、走进自然、分享交流，品味当地的人文底蕴与时代风貌。 燕山脚下的卢龙县是千年古县，这里浸润着独有的乡土气息。老马识途、李广射虎、金石为开……诸多耳熟能详的传说与成语典故发源于此。卢龙博物馆展厅内，一件件文物正在呈现当地的历史。 城市的另一头，青龙满族…"
