    "description": "2026年09月03日 朱志飞摄 \"> 9月1日，第十三届中华慈善奖在北京举行表彰大会，“南京理工大学瑞华暖心饭卡”成为唯一获奖的高校项目。 学生小关（化名）就是这个项目的受益者。8月27日下午，小关轻轻敲响南京理工大学（以下简称“南理工”）教育发展基金会一间办公室的门，他的来意有两个，一是分享即将升学的喜悦——自己就要去读硕士研究生了，二是感谢学校每个月的饭卡补贴。自大一下学期以来，小关的饭卡上每月都会收到310.5元补贴，3年多来累…",
    "content": "2026年09月03日 南理工食堂，工作人员正在出餐。 朱志飞摄 \"> 9月1日，第十三届中华慈善奖在北京举行表彰大会，“南京理工大学瑞华暖心饭卡”成为唯一获奖的高校项目。 学生小关（化名）就是这个项目的受益者。8月27日下午，小关轻轻敲响南京理工大学（以下简称“南理工”）教育发展基金会一间办公室的门，他的来意有两个，一是分享即将升学的喜悦——自己就要去读硕士研究生了，二是感谢学校每个月的饭卡补贴。自大一下学期以来，小关的饭卡上每月都会收到310.5元补贴，3年多来累计近万元。 “我还记得2023年春季学期的一个周…"
