    "description": "当地时间9月2日，波音宣布向卫星通信公司SES交付O3b mPOWER星座最后3颗卫星F11、F12和F13，标志着该项目首批13颗卫星星座完成交付。这3颗卫星计划于9月从美国佛罗里达州太空海岸发射，预计经过升轨和初始化后于2027年年中投入运营。O3b mPOWER运行于中地球轨道（MEO），可为政府机构、移动运营商、航空公司及邮轮等提供低时延、高吞吐量和专用带宽的连接服务。（界面）",
