    "description": "虽然这只是一个数据点，却足以让物理学家大吃一惊。2023至2024年间的某个时段，一台装载10吨超纯液氙的探测器记录到一次不同寻常的高能闪光。这类信号可能是穿行于银河系的大质量暗物质粒子与原子核发生碰撞所产生的。 如果这一观测结果能得到更多数据的支持，或许意味着人们终于发现了暗物质。这种不可见的物质被认为维系着星系，防止其分裂。它同时也将证实，暗物质由质量远大于质子的粒子构成，即弱相互作用大质量粒子（WIMP）。该粒子早已被理论预言，但…",
    "content": "虽然这只是一个数据点，却足以让物理学家大吃一惊。2023至2024年间的某个时段，一台装载10吨超纯液氙的探测器记录到一次不同寻常的高能闪光。这类信号可能是穿行于银河系的大质量暗物质粒子与原子核发生碰撞所产生的。 如果这一观测结果能得到更多数据的支持，或许意味着人们终于发现了暗物质。这种不可见的物质被认为维系着星系，防止其分裂。它同时也将证实，暗物质由质量远大于质子的粒子构成，即弱相互作用大质量粒子（WIMP）。该粒子早已被理论预言，但数十年来始终未被探测到。 美国南达科他州利德市桑福德地下研究设施的全球最大暗物质…"
