    "description": "9月1日，内蒙古呼伦贝尔根河市全面启动2026—2027年度供热采暖季。一名市民称，供暖后家里很暖和，冬天可以在室内穿背心。据根河市融媒体，根河有“中国冷极”之称，极端最低气温达-58℃，采暖期长达9个月，是全国供暖时间最早、供暖周期最长的城市之一。",
