    "title": "表弟醉后乱报警被传唤，表哥醉驾摩托冲进派出所“讨说法”涉嫌危险驾驶罪被立案侦查",
    "link": "https://m.thepaper.cn/detail/33993818",
    "pub_date": "2026-09-03 08:01:11",
    "author": "澎湃新闻记者 宫润泽 编辑 唐燕丽 素材来源 广西交警",
    "description": "近日，广西百色。一男子李某醉酒后驾驶摩托车直奔派出所，声称要找被传唤的表弟“讨说法”。民警发现其浑身酒气、意识混乱，经呼气检测达231mg/100ml，李某竟无所谓地表示“醉驾认账，吊销无所谓”。血检结果显示其血液酒精含量高达240.35mg/100ml。最终，李某驾驶证被吊销、5年内不得重考，并因涉嫌危险驾驶罪被立案侦查。",
    "content": "近日，广西百色。一男子李某醉酒后驾驶摩托车直奔派出所，声称要找被传唤的表弟“讨说法”。民警发现其浑身酒气、意识混乱，经呼气检测达231mg/100ml，李某竟无所谓地表示“醉驾认账，吊销无所谓”。血检结果显示其血液酒精含量高达240.35mg/100ml。最终，李某驾驶证被吊销、5年内不得重考，并因涉嫌危险驾驶罪被立案侦查。"
