    "title": "逛科技展会 93.9%受访青年曾被“惊艳”",
    "link": "https://www.chinanews.com.cn/edu/2026/09-03/10689196.shtml",
    "pub_date": "2026-09-03 07:55:36",
    "author": "",
    "description": "看人形机器人跳舞、与AI面对面、体验最新的科技产品……如今，各种主题的科技展会吸引了不少年轻人的目光，去科技展会“打卡”成为年轻人追赶科技潮流的重要方式。近日，中国青年报社社会调查中心联合问卷网(wenjuan.com)发布的一项1000名青年参与的调查显示，78.5%的受访青年参观过科技类展会。去科技展会“打卡”，66.8%的受访青年是因为对AI、机器人、新能源等领域感兴趣，41.3%的受访青年是为了解行业动向，助力职业或学业规划。",
    "content": "看人形机器人跳舞、与AI面对面、体验最新的科技产品……如今，各种主题的科技展会吸引了不少年轻人的目光，去科技展会“打卡”成为年轻人追赶科技潮流的重要方式。近日，中国青年报社社会调查中心联合问卷网(wenjuan.com)发布的一项1000名青年参与的调查显示，78.5%的受访青年参观过科技类展会。去科技展会“打卡”，66.8%的受访青年是因为对AI、机器人、新能源等领域感兴趣，41.3%的受访青年是为了解行业动向，助力职业或学业规划。"
