    "author": "澎湃新闻记者 宋承良",
    "description": "拜仁德国杯逆转晋级 北京时间9月3日凌晨，德国杯第一轮拜仁客场挑战奥斯纳布吕克。 主队开场5分钟打破僵局，好在凯恩马上扳平比分，比绍夫的进球将比分反超为2比1； 下半场奥利塞和凯恩分别进球，最终拜仁客场4比1逆转取胜，顺利晋级德国杯第二轮。 凯恩在连续7场德国杯比赛中取得进球，追平了拜仁慕尼黑队史连续进球场次纪录。此前只有两名球员做到过这一点：盖德·穆勒（1967年-1968年）和托马斯·穆勒（2013年-2014年）。他也在赛后接受采…",
    "content": "拜仁德国杯逆转晋级 北京时间9月3日凌晨，德国杯第一轮拜仁客场挑战奥斯纳布吕克。 主队开场5分钟打破僵局，好在凯恩马上扳平比分，比绍夫的进球将比分反超为2比1； 下半场奥利塞和凯恩分别进球，最终拜仁客场4比1逆转取胜，顺利晋级德国杯第二轮。 凯恩在连续7场德国杯比赛中取得进球，追平了拜仁慕尼黑队史连续进球场次纪录。此前只有两名球员做到过这一点：盖德·穆勒（1967年-1968年）和托马斯·穆勒（2013年-2014年）。他也在赛后接受采访时表示：“这是一场不错的比赛。在客场作战，而且气氛如此热烈，比赛从来都不轻松。…"
