    "description": "坐地铁不用掏手机，智能手表刷一下闸机就开了；开会不用记笔记，AI自动提炼待办事项；开车累了，智能驾驶上线提供服务……日新月异的科技正在不断改变我们的生活。近日，中国青年报社社会调查中心联合问卷网(wenjuan.com)发布的一项1000名青年参与的调查显示，44.1%的受访青年感觉近几年科技发展对生活改变很大，59.6%的受访青年希望未来科技发展能着重解决医疗健康及养老问题。",
